#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    if(scanf("%d",&n)!=1) return 0;
    vector<string> s(n);
    char buf[32];
    for(int i=0;i<n;i++){ scanf("%31s",buf); s[i]=buf; }

    // suf[j-1]: sufixos de tamanho j (j=1..9) das strings ja inseridas
    // pre[j-1]: prefixos de tamanho j (j=1..9) das strings ja inseridas
    // full: strings inteiras ja inseridas (cobre casos j=0 e j=10, duplicatas)
    array<unordered_set<string>,9> suf, pre;
    size_t cap=(size_t)n*2+16;
    for(int i=0;i<9;i++){ suf[i].reserve(cap); pre[i].reserve(cap); }
    unordered_set<string> full;
    full.reserve(cap);

    for(int k=0;k<n;k++){
        const string &cur=s[k];
        bool bad=false;

        // caso p=0 ou p=10 na concatenacao: S_k igual a alguma string anterior
        if(k>0 && full.count(cur)>0) bad=true;

        // caso 1<=p<=9 (j=10-p): prefixo de tamanho j de S_k igual ao
        // sufixo de tamanho j de S_a, e sufixo de tamanho 10-j de S_k
        // igual ao prefixo de tamanho 10-j de S_b (a==b permitido)
        for(int j=1;j<=9 && !bad;j++){
            if(suf[j-1].count(cur.substr(0,j))>0 &&
               pre[9-j].count(cur.substr(j,10-j))>0) bad=true;
        }

        if(bad){ printf("%s\n", cur.c_str()); return 0; }

        // insere dados de S_k (apenas depois de verifica-la)
        full.insert(cur);
        for(int j=1;j<=9;j++){
            suf[j-1].insert(cur.substr(10-j,j));
            pre[j-1].insert(cur.substr(0,j));
        }
    }
    printf("ok\n");
    return 0;
}
